<script setup lang="ts">
import { computed } from 'vue'
import { raceFeatures } from '../../../shared/workshop-race'
import { abilityMod, profBonus, type AbilityKey } from '../../lib/calc'
import { scheduleAt, workshopResourceAt, workshopSlots, type WorkshopDraft, type WorkshopStep } from '../../lib/homebrew-workshop'
const props=defineProps<{ draft:WorkshopDraft; step:WorkshopStep; level:number; scores:Record<AbilityKey,number> }>()
const emit=defineEmits<{ level:[value:number]; score:[key:AbilityKey,value:number] }>()
const slots=computed(()=>Object.entries(workshopSlots(props.draft,props.level)).filter(([,max])=>max>0))
const features=computed(()=>(props.draft.kind==='race'?raceFeatures(props.draft).map(f=>({...f,id:f.featureId!,level:f.level??1,choice:false,options:[] as string[]})):props.draft.features).filter(f=>f.level<=props.level).sort((a,b)=>a.level-b.level))
const resources=computed(()=>props.draft.resources.filter(r=>r.level<=props.level).map(r=>({...r,...workshopResourceAt(r,props.level,props.scores)})))
const casting=computed(()=>abilityMod(props.scores[props.draft.magic.ability])+profBonus(props.level))
const prepared=computed(()=>Math.max(1,(props.draft.magic.preparedLevel==='full'?props.level:props.draft.magic.preparedLevel==='half'?Math.floor(props.level/2):0)+abilityMod(props.scores[props.draft.magic.ability])+props.draft.magic.preparedBase))
</script>
<template><aside class="hw-preview" :data-focus="step" aria-label="Live homebrew preview"><div class="hw-panel"><p class="hw-eyebrow">LIVE RULES PREVIEW</p><h2>{{draft.name||'Your creation'}}</h2><p class="hw-hint">{{draft.kind==='race'?'Race':draft.kind==='subclass'?'Subclass':'Class'}} · {{draft.source||'Choose a source'}}</p><p v-if="draft.kind==='subclass'" class="hw-hint">Parent: {{draft.parentClass||'Not selected'}}</p><div class="hw-preview-controls"><label>Preview {{draft.kind==='race'?'character':'class'}} level <strong>{{level}}</strong><input :value="level" type="range" min="1" max="20" @input="emit('level',Number(($event.target as HTMLInputElement).value))" /></label><details><summary>Preview ability scores</summary><p class="hw-hint">Example scores used to calculate this preview.</p><div class="hw-preview-scores"><label v-for="(score,key) in scores" :key="key">{{key.toUpperCase()}}<input :value="score" type="number" min="1" max="35" @input="emit('score',key,Number(($event.target as HTMLInputElement).value))" /></label></div></details></div><dl class="hw-preview-facts"><template v-if="draft.kind==='race'&&draft.race"><div><dt>Size</dt><dd>{{draft.race.size}}</dd></div><div><dt>Speed</dt><dd>{{draft.race.speed}} ft</dd></div><div><dt>Darkvision</dt><dd>{{draft.race.darkvision}} ft</dd></div></template><div v-if="draft.kind==='class'"><dt>Hit die</dt><dd>d{{draft.hitDie}}</dd></div><div><dt>Proficiency</dt><dd>+{{profBonus(level)}}</dd></div><div v-if="draft.kind==='class'"><dt>Attacks</dt><dd>{{scheduleAt(draft.attacks,level)||1}}</dd></div><div v-if="draft.kind==='class'"><dt>ASI opportunities</dt><dd>{{draft.asiLevels.filter(l=>l<=level).length}}</dd></div></dl>
  <section v-if="draft.magic.enabled&&level>=draft.magic.startsAt" class="hw-preview-section hw-preview-magic"><h3>Spellcasting · {{draft.magic.ability.toUpperCase()}}</h3><div class="hw-preview-casting"><span>Attack <strong>{{casting>=0?'+':''}}{{casting}}</strong></span><span>Save DC <strong>{{8+casting}}</strong></span></div><div class="hw-preview-slots"><div v-for="[key,max] in slots" :key="key"><small>Spell level {{key.slice(1)}}</small><strong>{{max}}</strong><span>slots</span></div></div><p v-if="!slots.length" class="hw-hint">No spell slots at this level.</p><dl class="hw-preview-facts"><div><dt>Cantrips known</dt><dd>{{scheduleAt(draft.magic.cantrips,level)}}</dd></div><div><dt>{{draft.magic.learning==='prepared'?'Prepared spells':draft.magic.learning==='book'?'Spellbook total':'Spells known'}}</dt><dd>{{draft.magic.learning==='prepared'?prepared:scheduleAt(draft.magic.spells,level)}}</dd></div></dl><p v-if="draft.magic.learning==='book'" class="hw-hint">Prepared spell maximum: <strong>{{prepared}}</strong></p><p class="hw-hint">{{draft.magic.progression==='pact'?'Pact slots: short rest':'Spell slots: long rest'}} · {{draft.magic.spellList.length}} spells on the class list</p></section>
  <section v-if="resources.length" class="hw-preview-section hw-preview-resources"><h3>Resource pools</h3><article v-for="r in resources" :key="r.id" class="hw-preview-resource"><div class="hw-between"><strong>{{r.name||'Unnamed tracker'}}</strong><b>{{r.unlimited?'∞':r.maximum}}</b></div><small>{{r.formula}}</small><span>{{r.recovery==='manual'?'Manual recovery':r.recovery==='short'?'Short rest':'Long rest'}}</span></article></section>
  <section class="hw-preview-section hw-preview-features"><h3>Features at level {{level}} <span class="hw-pill">{{features.length}}</span></h3><p v-if="!features.length" class="hw-hint">Add a feature to see when it becomes available.</p><details v-for="feature in features" :key="feature.id" class="hw-preview-feature"><summary><span>{{feature.name||'Unnamed feature'}}</span><small>Level {{feature.level}}{{feature.choice?' · Choice':''}}</small></summary><p>{{feature.description||'No description yet.'}}</p><ul v-if="feature.choice"><li v-for="option in feature.options" :key="option">{{option}}</li></ul></details></section><p class="hw-preview-note">Preview only · these are example values, not changes to a character.</p></div></aside></template>
